import 'package:flutter/material.dart';
import 'package:font_awesome_flutter/font_awesome_flutter.dart';

class AnimatedIconExample extends StatefulWidget {
  const AnimatedIconExample({super.key});

  @override
  State<AnimatedIconExample> createState() => _AnimatedIconExampleState();
}

class _AnimatedIconExampleState extends State<AnimatedIconExample>
    with TickerProviderStateMixin {
  late AnimationController _rotationController;
  late AnimationController _scaleController;
  late Animation<double> _scaleAnimation;
  bool _isLiked = false;

  @override
  void initState() {
    super.initState();
    // 회전 애니메이션
    _rotationController = AnimationController(
      duration: const Duration(seconds: 2),
      vsync: this,
    )..repeat();

    // 스케일 애니메이션
    _scaleController = AnimationController(
      duration: const Duration(milliseconds: 200),
      vsync: this,
    );
    _scaleAnimation = Tween<double>(begin: 1.0, end: 1.3).animate(
      CurvedAnimation(parent: _scaleController, curve: Curves.easeInOut),
    );
  }

  @override
  void dispose() {
    _rotationController.dispose();
    _scaleController.dispose();
    super.dispose();
  }

  void _toggleLike() {
    setState(() {
      _isLiked = !_isLiked;
    });
    _scaleController.forward().then((_) => _scaleController.reverse());
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('아이콘 애니메이션')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            // 회전 애니메이션 (로딩)
            const Text('회전 애니메이션', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 16),
            Row(
              children: [
                RotationTransition(
                  turns: _rotationController,
                  child: const FaIcon(
                    FontAwesomeIcons.spinner,
                    size: 32,
                    color: Colors.blue,
                  ),
                ),
                const SizedBox(width: 24),
                RotationTransition(
                  turns: _rotationController,
                  child: const FaIcon(
                    FontAwesomeIcons.gear,
                    size: 32,
                    color: Colors.grey,
                  ),
                ),
                const SizedBox(width: 24),
                RotationTransition(
                  turns: _rotationController,
                  child: const FaIcon(
                    FontAwesomeIcons.circleNotch,
                    size: 32,
                    color: Colors.green,
                  ),
                ),
              ],
            ),
            const SizedBox(height: 32),

            // 좋아요 애니메이션
            const Text('탭 애니메이션', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 16),
            GestureDetector(
              onTap: _toggleLike,
              child: AnimatedBuilder(
                animation: _scaleAnimation,
                builder: (context, child) {
                  return Transform.scale(
                    scale: _scaleAnimation.value,
                    child: FaIcon(
                      _isLiked
                          ? FontAwesomeIcons.solidHeart
                          : FontAwesomeIcons.heart,
                      size: 48,
                      color: _isLiked ? Colors.red : Colors.grey,
                    ),
                  );
                },
              ),
            ),
            const SizedBox(height: 32),

            // 페이드 애니메이션
            const Text('색상 애니메이션', style: TextStyle(fontWeight: FontWeight.bold)),
            const SizedBox(height: 16),
            TweenAnimationBuilder<Color?>(
              tween: ColorTween(
                begin: Colors.grey,
                end: _isLiked ? Colors.red : Colors.grey,
              ),
              duration: const Duration(milliseconds: 300),
              builder: (context, color, child) {
                return FaIcon(
                  FontAwesomeIcons.solidStar,
                  size: 48,
                  color: color,
                );
              },
            ),
          ],
        ),
      ),
    );
  }
}

